WHERE directory.source_system_code = 'PRIMARY_HIS'
AND directory.diagnosis_category = #{query.diagnosisCategory.code}
AND (directory.disease_code LIKE '%' + #{query.keyword} + '%' OR directory.disease_name LIKE '%' + #{query.keyword} + '%' OR directory.mnemonic_code LIKE '%' + #{query.keyword} + '%')
